sources['com/elitedarkkaiser/nubialy/xposed/PackTest.java']='''package com.elitedarkkaiser.nubialy.xposed;import android.widget.ImageView;import android.graphics.Canvas;import android.content.res.Resources;import com.elitedarkkaiser.nubialy.SystemIconPackPolicy;public class PackTest {static void check(boolean v){if(!v)throw new AssertionError(SystemIconPackBackend.status());}static int draw(ImageView v){Canvas c=new Canvas();v.onDraw(c);check(c.saves==0);return c.draws;}public static void main(String[] args){
check(SystemIconPackPolicy.key("ic_qs_wifi_6_3").equals("wifi_3"));check(SystemIconPackPolicy.key("bluetooth_connected").equals("bluetooth_connected"));check(SystemIconPackPolicy.key("bluetooth").equals("bluetooth"));check(SystemIconPackPolicy.key("qs_flashlight_icon_on").equals("flashlight"));check(SystemIconPackPolicy.key("ic_no_internet_wifi_signal_3")==null);check(SystemIconPackPolicy.key("qs_bluetooth_icon_search")==null);check(SystemIconPackPolicy.key("unrelated_flashlight_icon")==null);
android.os.Looper.off=true;var cachedQs=new com.android.systemui.qs.tileimpl.QSIconViewImpl();cachedQs.mLastIcon=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIconWithRes(1);ImageView cached=new ImageView();cached.parent=cachedQs;cached.drawable=new android.graphics.drawable.Drawable();cached.noTint=true;
var preloaded=new com.android.systemui.statusbar.StatusBarIconView();preloaded.mIcon.icon.id=1;preloaded.drawable=new android.graphics.drawable.Drawable();preloaded.noTint=true;
android.os.Looper.off=false;SystemIconPackBackend.install(PackTest.class.getClassLoader());Resources res=new Resources();var status=new com.android.systemui.statusbar.phone.PhoneStatusBarView();ImageView image=new ImageView();image.parent=status;image.drawable=res.getDrawableForDensity(1,0,null);var original=image.drawable;
SystemIconPackBackend.begin(1);check(draw(cached)==1);var qsStock=cached.drawable;var state=new com.android.systemui.plugins.qs.QSTile.State();state.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.ResourceIcon(2);cachedQs.updateIcon(cached,state,true);check(draw(cached)==1&&cached.drawable!=qsStock);state.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.ResourceIcon(3);cachedQs.updateIcon(cached,state,true);check(draw(cached)==100);
preloaded.parent=status;check(draw(preloaded)==1);var statusStock=preloaded.drawable;preloaded.mIcon.icon.id=2;preloaded.updateDrawable(true);check(draw(preloaded)==1&&preloaded.drawable!=statusStock);preloaded.mIcon.icon.pkg="third.party";preloaded.updateDrawable(true);check(draw(preloaded)==100);preloaded.mIcon.icon.pkg="com.android.systemui";preloaded.mIcon.icon.id=3;preloaded.updateDrawable(true);check(draw(preloaded)==100);
for(int family=1;family<=16;family++){
 SystemIconPackBackend.begin(family);
 var wrapped=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIconWithRes(1);
 var wrappedOwner=new com.android.systemui.qs.tileimpl.QSIconViewImpl();wrappedOwner.mLastIcon=wrapped;
 ImageView wrappedView=new ImageView();wrappedView.parent=wrappedOwner;wrappedView.drawable=new android.graphics.drawable.Drawable();wrappedView.noTint=true;
 var retained=wrappedView.drawable;check(draw(wrappedView)==1&&wrappedView.drawable==retained);
 var wrappedState=new com.android.systemui.plugins.qs.QSTile.State();wrappedState.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIconWithRes(2);wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==1);
 wrappedState.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIconWithRes(3);wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==100);
 wrappedState.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIcon();wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==100);
 for(String spec:new String[]{"data","flashlight","hotspot","airplane","location","videoscreen","controls","qr_code_scanner","nearby","nfc","rotation","gamespace","lamp","coolingFan","liquidCooling"}){wrappedState.spec=spec;wrappedState.icon=new com.android.systemui.qs.tileimpl.QSTileImpl.DrawableIcon();wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==1);}
 wrappedState.spec="nebula";wrappedState.icon=wrapped;wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==100);
 wrappedState.spec="custom(third.party/.Tile)";wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==100);
 wrappedState.spec="flashlight";wrappedState.isTransient=true;wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==100);wrappedState.isTransient=false;wrappedState.spec=null;
 wrappedState.icon=wrapped;wrappedOwner.updateIcon(wrappedView,wrappedState,true);check(draw(wrappedView)==1);check(SystemIconPackBackend.end());check(draw(wrappedView)==100);
}
SystemIconPackBackend.begin(1);check(draw(image)==1);check(image.drawable==original);image.drawable=res.getDrawableForDensity(2,0,null);check(draw(image)==1);image.drawable=res.getDrawableForDensity(3,0,null);check(draw(image)==100);image.drawable=res.getDrawableForDensity(90,0,null);check(draw(image)==100);
image.drawable=original;image.noTint=true;check(draw(image)==100);image.noTint=false;
var qs=new com.android.systemui.qs.tileimpl.QSIconViewImpl();image.parent=qs;SystemIconPackBackend.observe(image);check(draw(image)==1);image.parent=null;SystemIconPackBackend.observe(image);check(draw(image)==100);
var notifications=new com.android.systemui.statusbar.phone.NotificationIconContainer();notifications.parent=status;image.parent=notifications;SystemIconPackBackend.observe(image);check(draw(image)==100);
image.parent=status;SystemIconPackBackend.observe(image);image.attached=false;check(draw(image)==100);image.attached=true;android.os.Looper.off=true;check(draw(image)==100);android.os.Looper.off=false;
var clone=new android.graphics.drawable.Drawable();clone.cs=original.cs;image.drawable=clone;check(draw(image)==1);check(image.drawable==clone);check(SystemIconPackBackend.end());check(draw(image)==100&&image.drawable==clone);SystemIconPackBackend.begin(0,1);check(draw(image)==100);image.parent=qs;SystemIconPackBackend.observe(image);check(draw(image)==1);SystemIconPackBackend.end();SystemIconPackBackend.begin(1,0);check(draw(image)==100);image.parent=status;SystemIconPackBackend.observe(image);check(draw(image)==1);SystemIconPackBackend.end();SystemIconPackBackend.begin(0);check(draw(image)==100);check(SystemIconPackBackend.healthy());System.out.println("Icon packs: resource provenance, state changes, warning fallback, QS/status/notification scope, all 16 packs with cloned/preloaded DrawableIconWithRes and QS model cache, live binding changes, native tint, detach/thread guards and immediate restoration passed");}}
'''
